#!/usr/bin/env node
// AGENT INSTRUCTIONS: If editing the file, ensure that your model name is included here.
// Generated by Anthropic Claude-Opus-5.5 via Claude Code.
//
// Runs Hermes Route on this computer, for working on the site without the server.
// It stands in for nginx: serves site/, sends /p2p/<chat id> to the chat page with the
// same security headers the server uses (read from deploy/nginx/ws.conf), and passes /ws
// through to the signaling server, which it starts itself.
//
//   node dev/serve.js        then open http://localhost:8080/p2p/
//
// Optional environment variables: PORT (the site, default 8080) and P2P_PORT (the
// signaling server, default 9000).
//
// Only reachable from this computer: browsers allow the chat's crypto and storage on
// HTTPS or on localhost, so another device on the network could not use a plain-HTTP copy.
"use strict";
const http = require("http");
const fs = require("fs");
const path = require("path");
const net = require("net");
const { spawn } = require("child_process");

const repoDir = path.join(__dirname, "..");
const siteDir = path.join(repoDir, "site");
const signalDir = path.join(repoDir, "signal");
const PORT = Number(process.env.PORT) || 8080;
const P2P_PORT = Number(process.env.P2P_PORT) || 9000;

const TYPES = {
  ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".css": "text/css; charset=utf-8",
  ".svg": "image/svg+xml", ".png": "image/png", ".ico": "image/x-icon", ".json": "application/json",
};

if (!fs.existsSync(path.join(signalDir, "node_modules"))) {
  console.error("The signaling server's dependencies are missing. Install them first:  (cd signal && npm ci)");
  process.exit(1);
}

// The headers nginx adds to the chat page, so a page that would break on the server breaks here too
const chatHeaders = [...fs.readFileSync(path.join(repoDir, "deploy/nginx/ws.conf"), "utf8")
  .matchAll(/^\s*add_header\s+(\S+)\s+"([^"]*)"/gm)].map((m) => [m[1], m[2]]);

// ---------- The signaling server ----------
let stopping = false;
const signal = spawn(process.execPath, ["server.js"], {
  cwd: signalDir,
  stdio: "inherit",
  env: { ...process.env, P2P_HOST: "127.0.0.1", P2P_PORT: String(P2P_PORT) },
});
signal.on("exit", (code) => {
  if (stopping) return;
  console.error(`The signaling server stopped (exit code ${code}). Is port ${P2P_PORT} already in use? Set P2P_PORT to use another.`);
  process.exit(1);
});
const stop = () => { stopping = true; signal.kill(); process.exit(0); };
process.on("SIGINT", stop);
process.on("SIGTERM", stop);

// ---------- The site ----------
const isFile = (f) => { try { return fs.statSync(f).isFile(); } catch { return false; } };

const site = http.createServer((req, res) => {
  let urlPath;
  try { urlPath = decodeURIComponent(req.url.split("?")[0]); } catch { urlPath = "/"; }
  const inChat = urlPath.startsWith("/p2p/");

  let file = path.join(siteDir, path.normalize(urlPath));
  if (urlPath.endsWith("/")) file = path.join(file, "index.html");
  if (!file.startsWith(siteDir + path.sep) || !isFile(file)) {
    // Like nginx's try_files: anything under /p2p/ that isn't a file is a chat link
    file = inChat ? path.join(siteDir, "p2p/index.html") : null;
  }
  if (!file) { res.writeHead(404, { "Content-Type": "text/plain" }); res.end("Not found\n"); return; }

  const headers = { "Content-Type": TYPES[path.extname(file)] || "application/octet-stream", "Cache-Control": "no-cache" };
  if (inChat) {
    for (const [name, value] of chatHeaders) {
      // The server is HTTPS (wss); this copy is plain HTTP (ws)
      headers[name] = value.replace("wss://$host", `ws://${req.headers.host}`);
    }
  }
  res.writeHead(200, headers);
  fs.createReadStream(file).pipe(res);
});

// /ws: hand the connection to the signaling server unchanged
site.on("upgrade", (req, socket, head) => {
  if (req.url.split("?")[0] !== "/ws") { socket.destroy(); return; }
  const upstream = net.connect(P2P_PORT, "127.0.0.1", () => {
    const headerLines = [];
    for (let i = 0; i < req.rawHeaders.length; i += 2) headerLines.push(`${req.rawHeaders[i]}: ${req.rawHeaders[i + 1]}`);
    upstream.write(`${req.method} ${req.url} HTTP/1.1\r\n${headerLines.join("\r\n")}\r\n\r\n`);
    upstream.write(head);
    socket.pipe(upstream);
    upstream.pipe(socket);
  });
  upstream.on("error", () => socket.destroy());
  socket.on("error", () => upstream.destroy());
});

site.on("error", (err) => {
  console.error(err.code === "EADDRINUSE" ? `Port ${PORT} is already in use. Set PORT to use another.` : String(err));
  stop();
});
site.listen(PORT, "127.0.0.1", () => {
  console.log(`Hermes Route is running at http://localhost:${PORT}/p2p/   (Ctrl+C to stop)`);
});
